import React, { useRef, useEffect } from 'react';
import { CalendarEvent } from '../types';

interface EventCardProps {
  event: CalendarEvent;
  onDragStart: (e: React.DragEvent, id: string) => void;
  onRenderRecord: (id: string) => void;
}

const categoryStyles = {
  Meeting: 'border-l-blue-400 text-blue-300',
  Deadline: 'border-l-rose-500 text-rose-300',
  'Focus block': 'border-l-emerald-400 text-emerald-300',
  Personal: 'border-l-amber-400 text-amber-300'
};

const RawEventCard: React.FC<EventCardProps> = ({
  event,
  onDragStart,
  onRenderRecord
}) => {
  const isFirstRender = useRef(true);

  useEffect(() => {
    // Notify monitor of this component render
    onRenderRecord(event.id);
  });

  return (
    <div
      draggable
      onDragStart={(e) => onDragStart(e, event.id)}
      className={`p-2.5 rounded bg-[#131b2e] border border-[#1e293b] border-l-[3px] ${
        categoryStyles[event.category]
      } shadow-md cursor-grab active:cursor-grabbing hover:bg-[#1a243c] transition-all select-none mb-2 text-left`}
    >
      <span className="text-[11px] font-mono text-slate-400 block mb-0.5">
        {event.time}
      </span>
      <h4 className="text-xs font-semibold text-slate-100 truncate">
        {event.title}
      </h4>
    </div>
  );
};

// Memoized version to selectively skip renders when props don't change
export const MemoizedEventCard = React.memo(RawEventCard);
export const UnmemoizedEventCard = RawEventCard;
